const fs = require("fs");
const files = fs.readFileSync("/tmp/subclass_files.txt", "utf8").split(/\r?\n/).filter(Boolean);
let totalEdits = 0;
for (const f of files) {
  let text = fs.readFileSync(f, "utf8");
  let out = "";
  let i = 0;
  let edits = 0;
  const tagRe = /<app-(fancy-pill|status-pill)\b/g;
  let m;
  let lastEnd = 0;
  while ((m = tagRe.exec(text)) !== null) {
    const tagStart = m.index;
    // find end of opening tag: scan forward for unquoted ">"
    let j = tagStart;
    let inQuote = null;
    while (j < text.length) {
      const ch = text[j];
      if (inQuote) {
        if (ch === inQuote) inQuote = null;
      } else {
        if (ch === "\"" || ch === "'") inQuote = ch;
        else if (ch === ">") break;
      }
      j++;
    }
    const tagEnd = j; // index of ">"
    const before = text.slice(lastEnd, tagStart);
    out += before;
    let tagText = text.slice(tagStart, tagEnd + 1);
    const newTagText = tagText
      .replace(/\[disableTooltip\]/g, () => { edits++; return "[hideHint]"; })
      .replace(/(\s)disableTooltip(\s|>|\/)/g, (mm, p1, p2) => { edits++; return p1 + "hideHint" + p2; });
    out += newTagText;
    lastEnd = tagEnd + 1;
  }
  out += text.slice(lastEnd);
  if (edits > 0) {
    fs.writeFileSync(f, out, "utf8");
    totalEdits += edits;
    console.log(f, edits);
  }
}
console.log("TOTAL", totalEdits);
'

